// One item per keyword to track. Edit this list.
// domain: the site whose position you want (no https://, no www).
return [
  { json: { keyword: 'running shoes', country: 'us', device: 'desktop', domain: 'nike.com' } },
  { json: { keyword: 'running shoes', country: 'us', device: 'mobile', domain: 'nike.com' } },
  { json: { keyword: 'trail running shoes', country: 'gb', device: 'desktop', domain: 'nike.com' } },
];

// One row per keyword: your best organic position (blank if not in the top results),
// the ranking URL, and whether Google showed an AI Overview that cites your domain.
const inputs = $('Keywords to track').all();
const day = new Date().toISOString().slice(0, 10);
const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch { return ''; } };
return $input.all().map((item, i) => {
  const { keyword, country, device, domain } = inputs[i].json;
  const { job, result } = item.json;
  if (!job || job.status !== 'completed') {
    return { json: { date: day, keyword, country, device, domain, position: '', url: '', title: '', ai_overview: '', ai_overview_cites_you: '', note: 'request failed (not charged)' } };
  }
  const mine = (u) => { const h = host(u); return h === domain || h.endsWith('.' + domain); };
  const hit = (result.organic_results || []).find((o) => mine(o.link));
  const ai = result.ai_overview;
  return { json: {
    date: day, keyword, country, device, domain,
    position: hit ? hit.position : '',
    url: hit ? hit.link : '',
    title: hit ? hit.title : '',
    ai_overview: ai ? 'yes' : 'no',
    ai_overview_cites_you: ai ? ((ai.sources || []).some((s) => mine(s.link)) ? 'yes' : 'no') : '',
    note: '',
  } };
});
